#define F_CPU 16000000UL

#include <avr/io.h>
#include <util/delay.h>
#include <stdint.h>

#define SCL_CLOCK 100000UL

/* MCP23008 7-bit address is 0x20.
   AVR TWI expects it shifted left with the R/W bit appended. */
#define LCD_ADDR (0x20 << 1)

#define MCP_IODIR 0x00
#define MCP_GPIO  0x09

/* Correct Adafruit/Tinkercad MCP23008 pin mapping. */
#define RS_BIT        0x02  /* GP1 */
#define EN_BIT        0x04  /* GP2 */
#define BACKLIGHT_BIT 0x80  /* GP7 */

static void i2c_init(void)
{
    /* Prescaler = 1. */
    TWSR = 0x00;

    /* 100 kHz I2C clock at a 16 MHz CPU clock. */
    TWBR = (uint8_t)(((F_CPU / SCL_CLOCK) - 16UL) / 2UL);

    TWCR = (1 << TWEN);
}

static void i2c_start(void)
{
    TWCR = (1 << TWINT) |
           (1 << TWSTA) |
           (1 << TWEN);

    while (!(TWCR & (1 << TWINT)))
    {
    }
}

static void i2c_write(uint8_t value)
{
    TWDR = value;

    TWCR = (1 << TWINT) |
           (1 << TWEN);

    while (!(TWCR & (1 << TWINT)))
    {
    }
}

static void i2c_stop(void)
{
    TWCR = (1 << TWINT) |
           (1 << TWSTO) |
           (1 << TWEN);

    while (TWCR & (1 << TWSTO))
    {
    }
}

static void mcp_write_register(uint8_t reg, uint8_t value)
{
    i2c_start();
    i2c_write(LCD_ADDR);
    i2c_write(reg);
    i2c_write(value);
    i2c_stop();
}

/*
 * LCD D4-D7 are connected to MCP23008 GP3-GP6.
 * Therefore, the four-bit nibble must be shifted left three positions.
 */
static void lcd_send_nibble(uint8_t nibble, uint8_t rs)
{
    uint8_t output;

    output = (uint8_t)((nibble & 0x0F) << 3);
    output |= BACKLIGHT_BIT;

    if (rs != 0)
    {
        output |= RS_BIT;
    }

    /* Ensure Enable begins low. */
    mcp_write_register(MCP_GPIO, output);
    _delay_us(1);

    /* Pulse Enable high. */
    mcp_write_register(MCP_GPIO, output | EN_BIT);
    _delay_us(1);

    /* Falling edge sends the nibble to the LCD. */
    mcp_write_register(MCP_GPIO, output);
    _delay_us(100);
}

static void lcd_send_byte(uint8_t value, uint8_t rs)
{
    lcd_send_nibble(value >> 4, rs);
    lcd_send_nibble(value & 0x0F, rs);
}

static void lcd_command(uint8_t command)
{
    lcd_send_byte(command, 0);

    if ((command == 0x01) || (command == 0x02))
    {
        _delay_ms(2);
    }
}

static void lcd_write_character(char character)
{
    lcd_send_byte((uint8_t)character, 1);
}

static void lcd_print(const char *text)
{
    while (*text != '\0')
    {
        lcd_write_character(*text);
        text++;
    }
}

static void lcd_init(void)
{
    i2c_init();
    _delay_ms(50);

    /* Configure all MCP23008 pins as outputs. */
    mcp_write_register(MCP_IODIR, 0x00);
    mcp_write_register(MCP_GPIO, BACKLIGHT_BIT);

    /*
     * HD44780 initialization sequence.
     * The LCD powers up expecting an eight-bit interface.
     */
    lcd_send_nibble(0x03, 0);
    _delay_ms(5);

    lcd_send_nibble(0x03, 0);
    _delay_ms(5);

    lcd_send_nibble(0x03, 0);
    _delay_us(150);

    /* Switch to four-bit mode. */
    lcd_send_nibble(0x02, 0);

    lcd_command(0x28); /* Four-bit mode, two lines, 5x8 font */
    lcd_command(0x0C); /* Display on, cursor off */
    lcd_command(0x01); /* Clear display */
    lcd_command(0x06); /* Increment cursor after each character */
}

/* Tinkercad/Arduino entry points. */
void setup(void)
{
    lcd_init();
    lcd_print("Hello World with Tracking");
}

